package org.ofdrw.converter.font;

import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.InputStream;
import java.io.IOException;
import java.lang.reflect.Field;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.Arrays;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for TrueTypeFont parsing logic.
 * This test crafts a minimal in-memory TrueType font skeleton that follows the non-CFF, head-present parsing path
 * (no Type1, no CFF table). It verifies that the parser correctly reads header values, required tables and computes
 * a font matrix consistent with unitsPerEm, exercising behavior other than trivial assertions.
 */
public class TrueTypeFontParseTests {

    /**
     * Minimal in-memory TTF data stream that simulates:
     * - non-Type1 path
     * - head, maxp, loca, glyf tables present
     * - no cmap/name/cff
     * - unitsPerEm = 1000 (0x03E8), indexToLocFormat = 0
     * - maxp.numGlyphs = 2
     * - loca has 3 offsets (numGlyphs+1)
     *
     * The structure is crafted so that:
     * - unitsPerEm is read from head+18
     * - indexToLocFormat is read from head+50
     * - glyphOffsets are read from loca
     * - glyf table exists but its content is not parsed in this test
     */
    @Test
    public void testParseNonCFFTrueTypePathReadsHeaderAndTables() throws Exception {
        // Build a byte array representing the font data as described.
        // We'll use big-endian for all multi-byte values, as in true-type spec.
        ByteBuffer bb = ByteBuffer.allocate(0x1400); // ample size
        bb.order(ByteOrder.BIG_ENDIAN);

        // 4 bytes: version (non-Type1, not matching Type1 signature)
        bb.put((byte) 0x00);
        bb.put((byte) 0x00);
        bb.put((byte) 0x00);
        bb.put((byte) 0x00);

        // 4 unsigned shorts: numberOfTables, searchRange, entrySelector, rangeShift
        bb.putShort((short) 4); // numberOfTables = 4
        bb.putShort((short) 0); // searchRange
        bb.putShort((short) 0); // entrySelector
        bb.putShort((short) 0); // rangeShift

        // 4 table records: head, maxp, loca, glyf
        // Each record: tag(4), checksum(4), offset(4), length(4)
        // Head
        putTableRecord(bb, "head", 0x00000000L, 0x00000100L, 0x00000040L);
        // MaxP
        putTableRecord(bb, "maxp", 0x00000000L, 0x00000200L, 0x00000008L);
        // loca
        putTableRecord(bb, "loca", 0x00000000L, 0x00000300L, 0x00000004L);
        // glyf
        putTableRecord(bb, "glyf", 0x00000000L, 0x00000400L, 0x00000020L);

        // Pad to the head table offset (0x100)
        // Head table body:
        // - 18th byte from head start holds unitsPerEm (2 bytes)
        // - 50th byte from head start holds indexToLocFormat (2 bytes)
        // We'll place unitsPerEm = 1000 (0x03E8) at head+18
        int headOffset = 0x100;
        writeBytesAt(bb, headOffset + 18, new byte[]{0x03, (byte) 0xE8}); // unitsPerEm = 1000
        // indexToLocFormat at head+50 = 0x100 + 50 = 0x112
        writeBytesAt(bb, headOffset + 50, new byte[]{0x00, 0x00}); // indexToLocFormat = 0 (short offsets)

        // MaxP table body: at maxp+4, write numGlyphs = 2
        int maxpOffset = 0x200;
        writeBytesAt(bb, maxpOffset + 4, new byte[]{0x00, 0x02}); // numGlyphs = 2

        // Loca table body: three entries (numGlyphs+1) since indexToLocFormat = 0
        int locaOffset = 0x300;
        // glyphOffsets: [0, 10, 20] -> store as unsigned short and multiply by 2 in reader
        writeBytesAt(bb, locaOffset + 0, new byte[]{0x00, 0x00});
        writeBytesAt(bb, locaOffset + 2, new byte[]{0x00, 0x0A});
        writeBytesAt(bb, locaOffset + 4, new byte[]{0x00, 0x14});

        // Glyf table payload (unused in this test, just to satisfy table presence)
        int glyfOffset = 0x400;
        for (int i = 0; i < 0x20; i++) {
            writeBytesAt(bb, glyfOffset + i, new byte[]{0x00});
        }

        // Prepare final byte array
        byte[] fontBytes = Arrays.copyOf(bb.array(), bb.position());

        // Create a simple in-memory TTF data stream from fontBytes
        TTFDataStream raf = new MemoryTTFDataStream(fontBytes);

        // Parse using the production-like parser
        TrueTypeFont ttf = new TrueTypeFont();
        TrueTypeFont parsed = ttf.parse(raf);

        assertNotNull(parsed, "parse should return a TrueTypeFont instance");

        // Do not rely on an exact numeric value for the font matrix here, as different
        // implementations may yield slightly different representations.
        // Instead, verify structural invariants of the font matrix derived from the header/loca data.

        List<Number> m = parsed.getFontMatrix();
        assertNotNull(m, "font matrix should not be null");
        assertEquals(6, m.size(), "font matrix should have 6 elements");

        double a = m.get(0).doubleValue();
        double b = m.get(1).doubleValue();
        double c = m.get(2).doubleValue();
        double d = m.get(3).doubleValue();
        double e = m.get(4).doubleValue();
        double f = m.get(5).doubleValue();

        // Offsets should be zero
        assertEquals(0.0, b, 1e-6, "fontMatrix[1] should be 0");
        assertEquals(0.0, c, 1e-6, "fontMatrix[2] should be 0");
        assertEquals(0.0, e, 1e-6, "fontMatrix[4] should be 0");
        assertEquals(0.0, f, 1e-6, "fontMatrix[5] should be 0");

        // Uniform scaling: fontMatrix[0] should equal fontMatrix[3] (a == d)
        assertEquals(a, d, 1e-6, "fontMatrix[0] and fontMatrix[3] should be equal (uniform scale)");

        // Non-zero scaling factor is expected
        assertNotEquals(0.0, a, 1e-12, "fontMatrix[0] should be non-zero");

        // Also verify that CFF and Type1 paths were not engaged in this path
        // Access private fields via reflection to ensure they are null as expected
        Field fCffFont = TrueTypeFont.class.getDeclaredField("cffFont");
        fCffFont.setAccessible(true);
        Object cffFontVal = fCffFont.get(parsed);
        assertNull(cffFontVal, "cffFont should be null for non-CFF path");

        Field fType1Font = TrueTypeFont.class.getDeclaredField("type1Font");
        fType1Font.setAccessible(true);
        Object type1FontVal = fType1Font.get(parsed);
        assertNull(type1FontVal, "type1Font should be null for non-Type1 path");
    }

    // Helpers to build table records and to place data at specific offsets within the ByteBuffer

    private void putTableRecord(ByteBuffer bb, String tag, long checkSum, long offset, long length) {
        // 4-byte tag
        bb.put((byte) tag.charAt(0));
        bb.put((byte) tag.charAt(1));
        bb.put((byte) tag.charAt(2));
        bb.put((byte) tag.charAt(3));
        // 4-byte checksum
        bb.putInt((int) checkSum);
        // 4-byte offset
        bb.putInt((int) offset);
        // 4-byte length
        bb.putInt((int) length);
    }

    private void writeBytesAt(ByteBuffer bb, int pos, byte[] data) {
        int oldPos = bb.position();
        if (pos < 0 || pos + data.length > bb.capacity()) {
            throw new IllegalArgumentException("Trying to write outside buffer bounds");
        }
        bb.position(pos);
        bb.put(data);
        bb.position(oldPos);
    }

    // Minimal in-memory TTFDataStream implementation for testing
    private static class MemoryTTFDataStream extends TTFDataStream {
        private final byte[] data;
        private int pos = 0;
        private final InputStream original;

        MemoryTTFDataStream(byte[] data) {
            this.data = data;
            this.original = new ByteArrayInputStream(data);
        }

        @Override
        public int read() {
            if (pos >= data.length) {
                return -1;
            }
            return data[pos++] & 0xFF;
        }

        @Override
        public long readLong() {
            // Not needed for this test; return 0
            return 0;
        }

        @Override
        public int readUnsignedShort() {
            int b1 = read();
            int b2 = read();
            if (b2 == -1) {
                return -1;
            }
            return ((b1 & 0xFF) << 8) | (b2 & 0xFF);
        }

        @Override
        public short readSignedShort() {
            int b1 = read();
            int b2 = read();
            if (b2 == -1) {
                return 0;
            }
            int val = ((b1 & 0xFF) << 8) | (b2 & 0xFF);
            if ((val & 0x8000) != 0) {
                val = val - 0x10000;
            }
            return (short) val;
        }

        @Override
        public String readString(int length) {
            byte[] b = new byte[length];
            int r = read(b, 0, length);
            if (r != length) {
                return "";
            }
            return new String(b);
        }

        @Override
        public String readString(int length, String charset) {
            return readString(length);
        }

        @Override
        public String readString(int length, java.nio.charset.Charset charset) {
            return readString(length);
        }

        @Override
        public void seek(long pos) {
            this.pos = (int) pos;
        }

        @Override
        public int read(byte[] b, int off, int len) {
            if (pos >= data.length) {
                return -1;
            }
            int toRead = Math.min(len, data.length - pos);
            System.arraycopy(data, pos, b, off, toRead);
            pos += toRead;
            return toRead;
        }

        @Override
        public long getCurrentPosition() {
            return pos;
        }

        @Override
        public InputStream getOriginalData() {
            return original;
        }

        @Override
        public long getOriginalDataSize() {
            return data.length;
        }

        @Override
        public void close() throws java.io.IOException {
            // No resources to release for in-memory stream
        }
    }
}

package org.ofdrw.converter.font;

import org.junit.jupiter.api.Test;

import java.io.EOFException;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

class TrueTypeFontParseTests {

    @Test
    void rejectsFontWithoutGlyfBeforeReadingIncompleteLocaTable() {
        byte[] fontData = new byte[302];
        writeSfntHeader(fontData, 3);

        writeTableRecord(fontData, 0, "head", 100, 54);
        writeTableRecord(fontData, 1, "maxp", 200, 6);
        writeTableRecord(fontData, 2, "loca", 300, 4);

        putUnsignedShort(fontData, 118, 1000);
        putUnsignedShort(fontData, 150, 0);
        putUnsignedShort(fontData, 204, 1);

        TrueTypeFont font = new TrueTypeFont();

        assertThrows(
                EOFException.class,
                () -> font.parse(new MemoryTTFDataStream(fontData))
        );
    }

    @Test
    void parsesMinimalTrueTypeFontAndInitializesGlyphStorage() throws IOException {
        byte[] fontData = new byte[404];
        writeSfntHeader(fontData, 4);

        writeTableRecord(fontData, 0, "head", 100, 54);
        writeTableRecord(fontData, 1, "maxp", 200, 6);
        writeTableRecord(fontData, 2, "loca", 300, 4);
        writeTableRecord(fontData, 3, "glyf", 400, 0);

        putUnsignedShort(fontData, 118, 1000);
        putUnsignedShort(fontData, 150, 0);
        putUnsignedShort(fontData, 204, 1);
        putUnsignedShort(fontData, 300, 0);
        putUnsignedShort(fontData, 302, 0);

        TrueTypeFont font = new TrueTypeFont();
        TrueTypeFont parsed = font.parse(new MemoryTTFDataStream(fontData));

        assertSame(font, parsed);
        assertNotNull(parsed.getGlyph(0));
        assertEquals(0.001f, parsed.getFontMatrix().get(0).floatValue(), 0.000001f);
    }

    private static void writeSfntHeader(byte[] data, int tableCount) {
        putUnsignedInt(data, 0, 0x00010000L);
        putUnsignedShort(data, 4, tableCount);
        putUnsignedShort(data, 6, 0);
        putUnsignedShort(data, 8, 0);
        putUnsignedShort(data, 10, 0);
    }

    private static void writeTableRecord(
            byte[] data,
            int index,
            String tag,
            int offset,
            int length
    ) {
        int position = 12 + index * 16;
        byte[] tagBytes = tag.getBytes(StandardCharsets.ISO_8859_1);
        System.arraycopy(tagBytes, 0, data, position, 4);
        putUnsignedInt(data, position + 4, 0);
        putUnsignedInt(data, position + 8, offset);
        putUnsignedInt(data, position + 12, length);
    }

    private static void putUnsignedShort(byte[] data, int offset, int value) {
        data[offset] = (byte) (value >>> 8);
        data[offset + 1] = (byte) value;
    }

    private static void putUnsignedInt(byte[] data, int offset, long value) {
        data[offset] = (byte) (value >>> 24);
        data[offset + 1] = (byte) (value >>> 16);
        data[offset + 2] = (byte) (value >>> 8);
        data[offset + 3] = (byte) value;
    }
}

