package org.ofdrw.layout.element.canvas;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

public class NamedColorRgbTests {

    @Test
    void testNamedColorBlue() {
        int[] rgb = NamedColor.rgb("Blue");
        assertArrayEquals(new int[]{0, 0, 255}, rgb);
    }

    @Test
    void testNamedColorWithWhitespaceAndCase() {
        int[] rgb = NamedColor.rgb("  Blue  ");
        assertArrayEquals(new int[]{0, 0, 255}, rgb);
    }

    @Test
    void testThreeDigitHexExpansion() {
        int[] rgb = NamedColor.rgb("#f0f");
        assertArrayEquals(new int[]{255, 0, 255}, rgb);
    }

    @Test
    void testRgbFunctionParse() {
        int[] rgb = NamedColor.rgb("rgb( 1 , 2 , 3 )");
        assertArrayEquals(new int[]{1, 2, 3}, rgb);
    }

    @Test
    void testRgbaFunctionParse() {
        int[] rgba = NamedColor.rgb("rgba(10, 20, 30, 0.5)");
        assertArrayEquals(new int[]{10, 20, 30, 127}, rgba);
    }

    @Test
    void testHexDecodeWith0xPrefix() {
        int[] rgb = NamedColor.rgb("0x1a2b3c");
        assertArrayEquals(new int[]{26, 43, 60}, rgb);
    }

    @Test
    void testUnknownColorReturnsNull() {
        assertNull(NamedColor.rgb("notacolor"));
    }

    @Test
    void testNullAndEmptyInputs() {
        assertNull(NamedColor.rgb(null));
        assertNull(NamedColor.rgb(""));
    }

    @Test
    void testWhitespaceOnlyThrowsException() {
        // As per specification, whitespace-only input may throw an unchecked exception after trimming
        assertThrows(RuntimeException.class, () -> NamedColor.rgb("   "));
    }
}

package org.ofdrw.layout.element.canvas;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertNotSame;

class NamedColorRgbTests {

    @Test
    void resolvesNamedColorIgnoringCaseAndSurroundingWhitespace() {
        int[] actual = NamedColor.rgb("  ReD  ");

        assertArrayEquals(new int[]{255, 0, 0}, actual);
    }

    @Test
    void expandsThreeDigitHexadecimalColor() {
        int[] actual = NamedColor.rgb(" #0f8 ");

        assertArrayEquals(new int[]{0, 255, 136}, actual);
    }

    @Test
    void parsesRgbAndRgbaValues() {
        assertArrayEquals(
                new int[]{12, 34, 56},
                NamedColor.rgb("RGB(12, 34, 56)")
        );
        assertArrayEquals(
                new int[]{12, 34, 56, 127},
                NamedColor.rgb("rgba(12, 34, 56, 0.5)")
        );
    }

    @Test
    void decodesSixDigitHexadecimalColor() {
        int[] actual = NamedColor.rgb("#336699");

        assertArrayEquals(new int[]{51, 102, 153}, actual);
    }

    @Test
    void returnsNullForNullEmptyAndUndecodableValues() {
        assertNull(NamedColor.rgb(null));
        assertNull(NamedColor.rgb(""));
        assertNull(NamedColor.rgb("not-a-color"));
    }

    @Test
    void recognizedColorsAreReturnedAsNewArrays() {
        int[] first = NamedColor.rgb("blue");
        int[] second = NamedColor.rgb("blue");

        assertNotNull(first);
        assertNotSame(first, second);
        assertArrayEquals(new int[]{0, 0, 255}, first);
        assertArrayEquals(new int[]{0, 0, 255}, second);
    }
}
